Running command: cat > /tmp/test_escape.c << 'EOF'
#include <stdio.h>
#include <string.h>
#include <ctype.h>

// Replicate the \u escape handling from json.c
static int parse_escape(const char *cp) {
    unsigned n;
    char uescape[5];
    unsigned u;
    cp++;  // skip the 'u'
    for (n = 0; n < 4 && isxdigit((int)*cp); n++) {
        uescape[n] = *cp++;
    }
    uescape[n] = '\0';
    --cp;
    if ((4 != n) || (1 != sscanf(uescape, "%4x", &u))) {
        return -1;
    }
    return 0;
}

int main(int argc, char **argv) {
    // Simulate a fuzzer input buffer: Size bytes + NUL, then poisoned
    // Input ends with \u (the 'u' is the last byte)
    char input[] = "{\"class\":\"TOFF\",\"device\":\"\\u";
    size_t size = strlen(input);
    printf("Input size: %zu\n", size);
    // Find the 'u' at the end
    const char *cp = input + size - 1;  // points to 'u'
    printf("Last char: %c (0x%02x)\n", *cp, (unsigned char)*cp);
    // Now simulate: cp points to 'u', cp++ skips it
    cp++;
    printf("After cp++: *cp = 0x%02x (NUL=%d)\n", (unsigned char)*cp, *cp == 0);
    // This reads *cp which is the NUL terminator - fine
    printf("isxdigit(0) = %d\n", isxdigit(0));
    return 0;
}
EOF
gcc -fsanitize=address -g -o /tmp/test_escape /tmp/test_escape.c && /tmp/test_escape

